def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a datetime.timedelta instance
    :type value: datetime.timedelta
    :return: total seconds as float
    """
    if value is None:
        return None
    try:
        total = value.total_seconds()
    except AttributeError:
        raise TypeError(f"Expected a datetime.timedelta instance, got {type(value).__name__}")
    except Exception as exc:
        raise RuntimeError(f"Error converting timedelta to total seconds: {exc}") from exc
    if not isinstance(total, (int, float)):
        raise TypeError(f"Unexpected result type from total_seconds: {type(total).__name__}")
    return total

def dehydrate_time(value):
    """Dehydrator for `time` values.

    Converts a time-like object to its ISO 8601 string representation.
    If the input is None, None is returned. If the input does not
    provide an ``isoformat`` method, a ``TypeError`` is raised.

    :param value: The time-like object to dehydrate.
    :type value: datetime.time or similar
    :return: ISO 8601 string representation of the time, or None.
    :raises TypeError: If ``value`` is not a time-like object.
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError("dehydrate_time expects a time-like object with an 'isoformat' method")
    except Exception as exc:
        # Re‑raise unexpected errors with context
        raise RuntimeError(f"Error dehydrating time: {exc}") from exc

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point
    :type value: Point
    :return: dict with x and y coordinates or None if invalid
    """
    if value is None:
        return None
    try:
        # Try attribute access
        if hasattr(value, "x") and hasattr(value, "y"):
            return {"x": value.x, "y": value.y}
        # Try sequence access
        if isinstance(value, (list, tuple)) and len(value) == 2:
            return {"x": value[0], "y": value[1]}
        # Unsupported type
        raise TypeError("Unsupported point type")
    except Exception:
        # In case of any unexpected error, return None
        return None

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to locate a dictionary-like attribute that holds the record data
        data = getattr(self, 'data', None)
        if data is None:
            data = getattr(self, 'record', None)
        if data is None:
            data = getattr(self, '_data', None)

        if data is None:
            raise AttributeError("No dictionary-like attribute found for keys.")

        if not isinstance(data, dict):
            raise TypeError("The located attribute is not a dictionary.")

        return list(data.keys())
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError to signal failure
        raise RuntimeError(f"Failed to retrieve keys: {exc}") from exc

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Try to locate a sequence attribute that holds the items
    seq = None
    for attr in ('items', 'data', 'list', 'array', 'values', 'elements', 'content', 'collection'):
        if hasattr(self, attr):
            val = getattr(self, attr)
            if isinstance(val, (list, tuple)):
                seq = val
                break
    # If no suitable attribute, try to use the object itself as an iterable
    if seq is None:
        try:
            seq = list(self)
        except TypeError:
            raise AttributeError("No suitable sequence attribute found and object is not iterable.")
    # Search for the key in the sequence
    try:
        return seq.index(key)
    except ValueError:
        raise ValueError(f"{key} is not present in the sequence.")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}") from e

def data(self, *keys):
        """ Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # Retrieve underlying key/value lists, defaulting to empty lists
        try:
            keys_list = self._keys
        except AttributeError:
            keys_list = []
        try:
            values_list = self._values
        except AttributeError:
            values_list = []

        # If no specific keys requested, return all items
        if not keys:
            return {k: v for k, v in zip(keys_list, values_list)}

        result = {}
        for key in keys:
            # Handle integer indices
            if isinstance(key, int):
                idx = key
                if idx < 0 or idx >= len(values_list):
                    raise IndexError(f"Index {idx} out of bounds")
                result[keys_list[idx]] = values_list[idx]
            else:
                # Treat as a key name
                if key in keys_list:
                    idx = keys_list.index(key)
                    result[key] = values_list[idx]
                else:
                    result[key] = None
        return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate arguments
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an integer, got {type(qid).__name__}")

    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    if not isinstance(dehydration_hooks, dict):
        raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
    if not isinstance(hydration_hooks, dict):
        raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")

    for name, func in handlers.items():
        if not callable(func):
            raise TypeError(f"handler '{name}' must be callable, got {type(func).__name__}")

    # Build the DISCARD message (protocol specific)
    # The actual message format may vary; here we use a simple list representation.
    # In a real implementation this would be encoded with a packstream writer.
    message = [0x0D, n, qid]  # 0x0D is a placeholder for the DISCARD message code

    # Append to the output queue
    try:
        if hasattr(self, "_output_queue"):
            self._output_queue.append(message)
        else:
            # If the queue attribute is missing, raise an informative error
            raise AttributeError("The object has no '_output_queue' attribute")
    except Exception as exc:
        raise RuntimeError("Failed to enqueue DISCARD message") from exc

    # Create and return a Response object
    try:
        # The Response constructor is assumed to accept the same arguments
        # as the discard method plus any additional handlers.
        response = Response(
            n=n,
            qid=qid,
            dehydration_hooks=dehydration_hooks,
            hydration_hooks=hydration_hooks,
            **handlers
        )
    except Exception as exc:
        raise RuntimeError("Failed to create Response object") from exc

    return response

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the name
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Validate fields
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    for f in fields:
        if not isinstance(f, str):
            raise TypeError("each field must be a string")
    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")
    # Ensure no duplicate field names
    if len(set(fields)) != len(fields):
        raise ValueError("duplicate field names in fields")
    # Prepare the class dictionary
    class_dict = {
        'fields': tuple(fields),
        'srid_map': srid_map,
    }
    # Define an __init__ that sets the field values
    def __init__(self, *args, **kwargs):
        # Call the base class __init__ if it exists
        try:
            super(self.__class__, self).__init__()
        except Exception:
            # Base class may not define __init__
            pass
        # Set positional arguments
        for field_name, value in zip(fields, args):
            setattr(self, field_name, value)
        # Set keyword arguments
        for key, value in kwargs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                raise AttributeError(f"Unknown field {key}")
    class_dict['__init__'] = __init__
    # Create the new subclass
    try:
        new_cls = type(name, (Point,), class_dict)
    except NameError as e:
        raise NameError("Base class 'Point' is not defined") from e
    except Exception as e:
        raise RuntimeError(f"Failed to create class {name}: {e}") from e
    return new_cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        @__import__('functools').wraps(func)
        def wrapper(*args, **kwargs):
            __import__('warnings').warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    try:
        parts = []
        current = ""
        for ch in s:
            if ch.isdigit():
                current += ch
            else:
                if current:
                    parts.append(int(current))
                    current = ""
        if current:
            parts.append(int(current))
        return tuple(parts)
    except Exception:
        return tuple()

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non‑negative number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    from collections import OrderedDict
    from functools import wraps

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable key that optionally includes argument types
            key_items = []
            for arg in args:
                key_items.append((arg, type(arg)) if typed else arg)
            for k, v in sorted(kwargs.items()):
                key_items.append((k, v, type(v)) if typed else (k, v))
            try:
                key = tuple(key_items)
            except TypeError:
                # Unhashable arguments; bypass caching
                return func(*args, **kwargs)

            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, ts = entry
                if now - ts <= ttl:
                    # Move to the end to mark as recently used
                    cache.move_to_end(key)
                    return value
                # Entry expired; remove it
                del cache[key]

            # Compute the result and cache it
            result = func(*args, **kwargs)
            cache[key] = (result, now)
            # Ensure cache size does not exceed maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be >= 0 or None")
    def decorating_function(user_function):
        cache = {}
        order = []  # most recent first
        hits = misses = 0

        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # sort kwargs to make key order-independent
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            try:
                hash(key)
            except TypeError:
                raise TypeError("Arguments must be hashable")
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs)
            if key in cache:
                # Move key to front (most recent)
                order.remove(key)
                order.insert(0, key)
                hits += 1

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except TypeError as e:
        raise ValueError(f"Invalid or unhashable key: {key}") from e
    except Exception as e:
        raise RuntimeError(f"Error setting default for key {key}") from e

