def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        # Use the class name of the current instance
        name = self.__class__.__name__
        # Strip known suffixes
        for suffix in ("Py", "Fallback"):
            if name.endswith(suffix):
                return name[:-len(suffix)]
        return name
    except Exception as exc:
        raise RuntimeError("Unable to determine target class") from exc

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")
    result = {}
    try:
        for name in dir(self):
            # Skip private and special attributes unless requested
            if not all and name.startswith('_'):
                continue
            if name.startswith('__') and name.endswith('__'):
                continue
            try:
                value = getattr(self, name)
            except Exception:
                continue
            # Skip methods and other callables
            if callable(value):
                continue
            # Attempt to retrieve a docstring
            doc = getattr(value, "__doc__", None)
            if doc is None:
                # Fallback: check the class attribute
                cls = self.__class__
                if hasattr(cls, name):
                    try:
                        class_attr = getattr(cls, name)
                        doc = getattr(class_attr, "__doc__", None)
                    except Exception:
                        doc = None
                if doc is None:
                    doc = ""
            result[name] = doc
    except Exception:
        # In case of unexpected errors, return an empty mapping
        return {}
    return result

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except Exception:
        # If the required function is not available or raises an error,
        # assume optimizations are ignored.
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are needed
        return True
    except Exception:
        # Unexpected error, default to requiring C optimizations
        return True

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context to an empty dictionary
        try:
            self._context = {}
        except AttributeError:
            # If the attribute does not exist, create it
            self._context = {}

        # Reinitialize bins
        try:
            # If an initial value was provided during construction, use it
            if hasattr(self, "_initial_value") and self._initial_value is not None:
                # Preserve the number of bins if they already exist
                if hasattr(self, "_bins") and isinstance(self._bins, list):
                    self._bins = [self._initial_value for _ in self._bins]
                else:
                    # If bins are not yet defined, create a single bin with the initial value
                    self._bins = [self._initial_value]
            else:
                # No initial value; use the make_bins method to create bins
                if hasattr(self, "make_bins") and callable(self.make_bins):
                    self._bins = self.make_bins()
                else:
                    # Fallback: empty list of bins
                    self._bins = []
        except Exception as e:
            # In case of any unexpected error, log it and set bins to an empty list
            # (Assuming a logger is available; otherwise, silently ignore)
            try:
                if hasattr(self, "logger"):
                    self.logger.error(f"Failed to reset bins: {e}")
            except Exception:
                pass
            self._bins = []

def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.
        """
        # Validate separator
        if not isinstance(separator, str):
            raise TypeError(f"separator must be a string, got {type(separator).__name__}")
        # Validate header
        if header is not None and not isinstance(header, str):
            raise TypeError(f"header must be a string or None, got {type(header).__name__}")

        # Ensure points iterable
        try:
            points_iter = iter(self.points)
        except AttributeError:
            raise AttributeError("Graph object has no 'points' attribute or it is not iterable")

        lines = []

        # Add header if provided
        if header is not None:
            lines.append(header)

        for point in points_iter:
            # Each point is expected to be a tuple (coordinate, value)
            try:
                coordinate, value = point
            except Exception:
                # If point is not a tuple of length 2, treat entire point as coordinate
                coordinate = point
                value = None

            # Convert coordinate to string parts
            if isinstance(coordinate, (list, tuple)):
                coord_parts = [str(c) for c in coordinate]
            else:
                coord_parts = [str(coordinate)]

            # Convert value to string parts
            if value is None:
                value_parts = []
            elif isinstance(value, (list, tuple)):
                value_parts = [str(v) for v in value]
            elif isinstance(value, str):
                value_parts = [value]
            else:
                value_parts = [str(value)]

            # Combine parts
            line_parts = coord_parts + value_parts
            line = separator.join(line_parts)
            lines.append(line)

        # Join all lines with newline
        return "\n".join(lines) + ("\n" if lines else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string.")
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute.")
    err_indices = self._err_indices
    if isinstance(err_indices, dict):
        try:
            return err_indices[coord_name]
        except KeyError:
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices.") from None
    elif isinstance(err_indices, list):
        for name, indices in err_indices:
            if name == coord_name:
                return indices
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")
    else:
        raise TypeError("Unsupported type for '_err_indices' attribute.")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Direct FillRequest instance
        if isinstance(seq, FillRequest):
            return True
        # Exclude Source sequences
        if isinstance(seq, Source):
            return False
        # Strings and bytes are iterable but not sequences of elements
        if isinstance(seq, (str, bytes)):
            return False
        # Try to iterate over seq
        iterator = iter(seq)
    except Exception:
        return False
    # Check for at least one FillRequest element
    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False

