def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    if not os.path.isfile(zip_path):
        raise ValueError(f"Path is not a file: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First, identify all XML files to determine package basenames
            xml_basenames = set()
            for name in zf.namelist():
                if name.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(name))[0]
                    xml_basenames.add(base)

            # Group all files that share the same basename as an XML file
            for name in zf.namelist():
                base = os.path.splitext(os.path.basename(name))[0]
                if base in xml_basenames:
                    try:
                        data = zf.read(name)
                    except Exception:
                        # Skip files that cannot be read
                        continue
                    if base not in packages:
                        packages[base] = {}
                    packages[base][name] = data
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        # Catch any other unexpected errors and re-raise as ValueError
        raise ValueError(f"Error processing zip file {zip_path}: {e}") from e

    return packages

