def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Se nenhum XPath encontrar um resultado, retorna None.
    """
    # Validate inputs
    if node is None:
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        return None

    for xpath in pubdate_xpaths:
        try:
            # Execute XPath; lxml returns a list of results
            results = node.xpath(xpath)
            if not results:
                continue
            # Prefer string results; otherwise try to get text from element
            first = results[0]
            if isinstance(first, str):
                return first
            # If it's an element, return its text content if available
            if hasattr(first, 'text') and first.text is not None:
                return first.text
            # Fallback: return the element itself
            return first
        except Exception:
            # Ignore malformed XPath or evaluation errors and continue
            continue
    # No match found
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    # Helper to format objects recursively
    def _format(obj, level, visited):
        # Avoid infinite recursion
        obj_id = id(obj)
        if obj_id in visited:
            return "<Recursion>"
        visited.add(obj_id)

        # Primitive types
        if isinstance(obj, (str, int, float, bool, type(None))):
            return repr(obj)

        # Dictionaries
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in obj.items():
                key_repr = repr(k)
                val_repr = _format(v, level + 1, visited)
                items.append(" " * ((level + 1) * indent) + f"{key_repr}: {val_repr}")
            return "{\n" + ",\n".join(items) + "\n" + " " * (level * indent) + "}"

        # Lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                return type(obj).__name__ + "()"
            items = []
            for item in obj:
                items.append(" " * ((level + 1) * indent) + _format(item, level + 1, visited))
            if isinstance(obj, list):
                opening, closing = "[\n", "]"
            elif isinstance(obj, tuple):
                opening, closing = "(\n", ")"
            else:  # set
                opening, closing = "{\n", "}"
            return opening + ",\n".join(items) + "\n" + " " * (level * indent) + closing

        # Custom objects
        if hasattr(obj, "__dict__"):
            return f"{obj.__class__.__name__}(" + _format(obj.__dict__, level, visited) + ")"
        if hasattr(obj, "__slots__"):
            slots = {slot: getattr(obj, slot) for slot in obj.__slots__ if hasattr(obj, slot)}
            return f"{obj.__class__.__name__}(" + _format(slots, level, visited) + ")"

        # Fallback
        return repr(obj)

    try:
        result = _format(self, 0, set())
        if debug:
            result += f"\n# Debug: type={type(self).__name__}"
        return result
    except Exception as e:
        return f"<Error pretty printing: {e}>"

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate hook
    if hook is None:
        raise ValueError("Hook cannot be None")
    # Ensure registry exists and is a dict
    if not hasattr(self, "_hook_registry"):
        self._hook_registry = {}
    if not isinstance(self._hook_registry, dict):
        raise TypeError("Hook registry must be a dictionary")
    # Ensure hook key exists
    try:
        if hook not in self._hook_registry:
            self._hook_registry[hook] = []
    except TypeError as e:
        raise TypeError(f"Hook {hook!r} is not hashable and cannot be used as a key") from e

    def decorator(func):
        if not callable(func):
            raise TypeError(f"Listener {func!r} is not callable")
        # Register the function
        try:
            listeners = self._hook_registry[hook]
            if func not in listeners:
                listeners.append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register listener for hook {hook!r}") from e
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if result is None:
            return None
        # Detect Python 2 by presence of the unicode type
        try:
            if isinstance(result, unicode):
                # Encode to bytes using UTF-8
                return result.encode('utf-8')
        except NameError:
            # unicode not defined, running on Python 3
            pass
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default version to return if any error occurs
    default_version = "0.0.0"
    try:
        # Try to import importlib.metadata (Python 3.8+)
        try:
            import importlib.metadata as importlib_metadata
        except Exception:
            # Fallback for older Python versions
            import importlib_metadata  # type: ignore
        # Determine the package name from the current module
        pkg_name = __package__ or __name__
        # If running as a script, __package__ may be None or "__main__"
        if not pkg_name or pkg_name == "__main__":
            # Attempt to find a distribution that contains this file
            try:
                import pathlib
                file_path = pathlib.Path(__file__).resolve()
                for dist in importlib_metadata.distributions():
                    if file_path in dist.files:
                        return dist.version
            except Exception:
                # If any of the above fails, fall back to default
                return default_version
        # Try to get the version of the package
        try:
            return importlib_metadata.version(pkg_name)
        except Exception:
            # If the package name is not found, try to find a distribution by file path
            try:
                import pathlib
                file_path = pathlib.Path(__file__).resolve()
                for dist in importlib_metadata.distributions():
                    if file_path in dist.files:
                        return dist.version
            except Exception:
                return default_version
    except Exception:
        # Any unexpected error results in the default version
        return default_version
    # If all attempts fail, return the default
    return default_version

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalize pieces to a list
    if isinstance(pieces, str):
        pieces = [pieces]
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of version components")
    # Filter out None values and convert to string
    pieces_str = [str(p) for p in pieces if p is not None]
    # Handle empty input
    if not pieces_str:
        return ""
    # Normalize style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    try:
        if style == "semver":
            # Ensure at least three components
            major = pieces_str[0] if len(pieces_str) > 0 else "0"
            minor = pieces_str[1] if len(pieces_str) > 1 else "0"
            patch = pieces_str[2] if len(pieces_str) > 2 else "0"
            return f"{major}.{minor}.{patch}"
        elif style == "pep440":
            # Join all components with dots
            return ".".join(pieces_str)
        elif style == "short":
            # Return the first two components if available
            if len(pieces_str) >= 2:
                return f"{pieces_str[0]}.{pieces_str[1]}"
            return pieces_str[0]
        elif style == "full":
            return ".".join(pieces_str)
        else:
            raise ValueError(f"Unsupported style: {style}")
    except Exception as exc:
        # Re-raise with a clearer message
        raise RuntimeError(f"Error rendering version: {exc}") from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # Check if any element in pieces contains a '+'
        for element in pieces:
            if '+' in str(element):
                return '.'
        return '+'
    except Exception:
        # If pieces is not iterable or any error occurs, default to '+'
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    # Normalize commands to a list
    if isinstance(commands, str):
        # If a single string is provided, split it into arguments
        commands = shlex.split(commands)
    elif not isinstance(commands, (list, tuple)):
        raise TypeError(f"commands must be a string or a list/tuple of strings, got {type(commands).__name__}")

    # Ensure args is a list
    if args is None:
        args = []
    elif not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a list or tuple of strings, got {type(args).__name__}")

    # Build the full command
    full_cmd = list(commands) + list(args)

    # Prepare subprocess parameters
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True,
        "capture_output": True,
    }

    if hide_stderr:
        run_kwargs["stderr"] = subprocess.DEVNULL

    if verbose:
        print(f"Running command: {' '.join(shlex.quote(arg) for arg in full_cmd)}")

    try:
        result = subprocess.run(full_cmd, **run_kwargs)
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command: {' '.join(full_cmd)}") from e

    if result.returncode != 0:
        # Include stderr in the error message unless it was hidden
        err_msg = result.stderr if not hide_stderr else ""
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=err_msg
        )

    return result.stdout

