    for action in actions:
        try:
            option_strings = getattr(action, 'option_strings', None)
            if option_strings:
                flags.extend(option_strings)
            else:
                dest = getattr(action, 'dest', None)
                if dest:
                    flags.append(dest)
        except Exception:
            # Skip any action that causes an unexpected error
            continue
    return ' '.join(flags)

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generate pages
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # In case of unexpected errors during iteration
        raise RuntimeError(f"Error while paging through response: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    try:
        iter(dicts)
    except TypeError:
        raise TypeError("Input must be an iterable of dictionaries")

    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"All elements must be dictionaries, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as exc:
                    raise TypeError(f"Cannot sum values for key {key!r}: {exc}") from exc
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        s = val.strip().lower()
        return s in {"none", "null", "nil", "na", "n/a", ""}
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # Try to access the internal actions list
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Provided object does not appear to be an argparse.ArgumentParser")
    # Collect all option strings from actions
    flags = []
    for action in actions:
        # action.option_strings is a list of flag strings (e.g., ['-a', '--alpha'])
        try:
            opt_strs = action.option_strings
        except AttributeError:
            continue
        if opt_strs:
            flags.extend(opt_strs)
    # Return space-separated string
    return ' '.join(flags) if flags else ''

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: Modified dictionary with the key replaced
    """
    # Basic validation
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, (int, str)):
        raise TypeError("register_number must be an int or str")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key name")

    def _recursive_replace(d):
        # Use list to avoid RuntimeError due to dict size change during iteration
        for key in list(d.keys()):
            try:
                if key == register_value:
                    # Replace key with register_number
                    d[register_number] = d[key]
                    del d[key]
                else:
                    val = d[key]
                    if isinstance(val, dict):
                        _recursive_replace(val)
                    elif isinstance(val, list):
                        for item in val:
                            if isinstance(item, dict):
                                _recursive_replace(item)
            except Exception:
                # Skip problematic entries but continue processing
                continue

    try:
        _recursive_replace(flow_params)
    except Exception as e:
        # If any unexpected error occurs, raise a RuntimeError with context
        raise RuntimeError(f"Failed to replace register key: {e}") from e

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise ValueError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    result = set()
    try:
        for sub in cls.__subclasses__():
            result.add(sub)
            result.update(subclasses(sub))
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve subclasses of {cls}") from exc
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError("string must be a str")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")

    # Validate alphabet
    if len(alphabet) == 0:
        raise ValueError("alphabet must not be empty")
    seen = set()
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise TypeError("alphabet elements must be single-character strings")
        if ch in seen:
            raise ValueError("alphabet contains duplicate characters")
        seen.add(ch)

    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    # Validate string
    if string == "":
        raise ValueError("string must not be empty")

    result = 0
    for c in string:
        if c not in char_to_value:
            raise ValueError(f"character '{c}' not in alphabet")
        result = result * base + char_to_value[c]

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Basic input validation
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise ValueError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists
    try:
        if destination_path.exists():
            if not destination_path.is_dir():
                raise ValueError(f"destination_path '{destination_path}' exists but is not a directory")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to prepare destination directory '{destination_path}': {exc}") from exc

    # Download the archive
    try:
        import requests
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(f"Failed to download archive from '{url}': {exc}") from exc

    # Write to a temporary file
    import tempfile
    temp_file = None
    try:
        temp_file = tempfile.NamedTemporaryFile(delete=False)
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                temp_file.write(chunk)
        temp_file.close()
    except Exception as exc:
        if temp_file:
            try:
                temp_file.close()
            except Exception:
                pass
        raise RuntimeError(f"Failed to write downloaded data to temporary file: {exc}") from exc

    # Extract the archive
    try:
        import tarfile
        with tarfile.open(temp_file.name, "r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except tarfile.TarError as exc:
        raise RuntimeError(f"Failed to extract archive '{temp_file.name}': {exc}") from exc
    finally:
        # Clean up temporary file
        try:
            import os
            os.remove(temp_file.name)
        except Exception:
            pass

    return destination_path

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    # Strip leading and trailing single or double quotes
    return name.strip('\'"')

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False
    # Direct string check for common localhost names
    if host.lower() == "localhost":
        return True
    try:
        # Resolve the host to all possible addresses
        addr_info = socket.getaddrinfo(host, None)
    except (socket.gaierror, socket.herror, socket.timeout):
        return False
    for info in addr_info:
        # info[4] is a tuple like (address, port, flowinfo, scopeid) for IPv6
        address = info[4][0]
        if address in ("127.0.0.1", "::1"):
            return True
    return False

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if find_paths is None:
        return []
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")
    result = []
    for p in iterator:
        if not isinstance(p, str):
            raise TypeError(f"find_paths elements must be strings, got {type(p)}")
        # Treat strings containing a scheme (e.g., 'sh:' or 'pp:') as patterns
        if re.match(r'^[a-zA-Z]+:', p):
            result.append(p)
        else:
            result.append(f'sh:**/*{p}*/**')
    return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only consider Windows environments
        if os.name != 'nt':
            return False

        # Check common environment variables set by Git Bash
        ostype = os.environ.get('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True

        msystem = os.environ.get('MSYSTEM', '').lower()
        if msystem.startswith('mingw') or msystem.startswith('msys'):
            return True

        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer representing file permissions")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Ensure parent directories exist
    dirpath = os.path.dirname(os.path.abspath(config_filename))
    if dirpath and not os.path.isdir(dirpath):
        try:
            os.makedirs(dirpath, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories '{dirpath}': {exc}") from exc

    # Check for existing file
    if os.path.exists(config_filename):
        if not overwrite:
            raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")
        # If overwrite is True, we will replace the file

    # Write the configuration
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc

    # Set file permissions
    try:
        os.chmod(config_filename, mode)
    except OSError as exc:
        # If chmod fails, we still consider the file written; log or re-raise as needed
        raise OSError(f"Failed to set permissions on '{config_filename}': {exc}") from exc

    return None

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    try:
        if not isinstance(pattern, str):
            raise TypeError("pattern must be a string")
        if strip:
            pattern = pattern.strip()
        # Escape regex special characters
        regex_pattern = re.escape(pattern)
        return regex_pattern
    except Exception as e:
        raise ValueError(f"Error converting pattern to regex: {e}") from e

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        ipaddress.IPv4Address(target)
        return True
    except Exception:
        return False

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        if x is None:
            raise ValueError("Input cannot be None")
        x_arr = np.asarray(x)
        if x_arr.size == 0:
            raise ValueError("Input array is empty")
        if not np.issubdtype(x_arr.dtype, np.number):
            raise TypeError("Input must be numeric")
        mean = 0.2
        sigma = 0.1
        return np.exp(-((x_arr - mean) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise RuntimeError(f"Error computing Gaussian: {e}") from e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re
    import logging

    configs = {}
    error_records = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    msg = f'JSON decode error in {filename}: {e}'
                    record = logging.LogRecord('config_loader', logging.ERROR,
                                               filename, 0, msg, None, None)
                    error_records.append(record)
                    continue

                # Basic validation: config must be a dict
                if not isinstance(data, dict):
                    msg = f'Configuration in {filename} is not a JSON object (dict).'
                    record = logging.LogRecord('config_loader', logging.ERROR,
                                               filename, 0, msg, None, None)
                    error_records.append(record)
                    continue

                # Resolve environment variables if requested
                if resolve_env:
                    data = resolve_env_vars(data)

                # Apply overrides if provided
                if overrides and isinstance(overrides, dict):
                    # shallow merge: overrides take precedence
                    merged = data.copy()
                    merged.update(overrides)
                    data = merged

                configs[filename] = data

        except FileNotFoundError as e:
            msg = f'File not found: {filename}'
            record = logging.LogRecord('config_loader', logging.ERROR,
                                       filename, 0, msg, None, None)
            error_records.append(record)
        except Exception as e:
            # Catch any other unexpected errors
            msg = f'Unexpected error loading {filename}: {e}'
            record = logging.LogRecord('config_loader', logging.ERROR,
                                       filename, 0, msg, None, None)
            error_records.append(record)

    return configs, error_records

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of protocol handlers from the class.
    # If the attribute is missing or not a dict, treat it as empty.
    try:
        handlers = getattr(cls, "_protocol_handlers", {})
        if not isinstance(handlers, dict):
            raise TypeError("Protocol handlers mapping must be a dict")
    except Exception:
        handlers = {}

    # If no specific protocol version is requested, return a copy
    # of all available handlers.
    if protocol_version is None:
        return dict(handlers)

    # Validate the provided protocol_version.
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    # Return the handler for the requested version if it exists.
    handler = handlers.get(protocol_version)
    if handler is None:
        return {}
    return {protocol_version: handler}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    try:
        if values is None:
            raise ValueError("values cannot be None")
        # Ensure values is iterable
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        # Validate each element and collect raw strings
        raw_list = []
        for v in iterator:
            if not isinstance(v, str):
                raise ValueError(f"Bookmark value must be a string, got {type(v).__name__}")
            raw_list.append(v)
        # Instantiate the Bookmarks object
        try:
            instance = cls()
        except Exception as e:
            raise ValueError(f"Could not instantiate {cls.__name__}: {e}") from e
        # Attempt to store the raw values in the instance
        if hasattr(instance, "add_raw_value") and callable(getattr(instance, "add_raw_value")):
            for rv in raw_list:
                instance.add_raw_value(rv)
        elif hasattr(instance, "raw_values"):
            instance.raw_values = raw_list
        else:
            # Fallback: store in a private attribute
            instance._raw_values = raw_list
        return instance
    except Exception as exc:
        raise ValueError(f"Failed to create Bookmarks from raw values: {exc}") from exc

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    except TypeError as e:
        raise TypeError(f"unhashable type: '{type(key).__name__}'") from e
    del self[key]
    return value

def popitem(self):
    """
    Remove and return the (key, value) pair most recently used.
    Raises KeyError if the cache is empty.
    """
    # Attempt to use an internal OrderedDict-like cache if present
    cache = getattr(self, "_cache", None)
    if cache is not None:
        try:
            # Prefer the most recently used (last) item
            return cache.popitem(last=True)
        except TypeError:
            # Fallback if the popitem signature doesn't accept 'last'
            try:
                return cache.popitem()
            except KeyError:
                raise KeyError("popitem(): dictionary is empty")
    # Fallback to the base dict behavior (insertion order)
    try:
        return super().popitem()
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches "IN" followed by optional whitespace, an opening parenthesis,
        # optional whitespace, a placeholder starting with ':' and word characters,
        # optional whitespace, and a closing parenthesis.
        pattern = r'\bIN\s*\(\s*(:\w+)\s*\)'
        return re.compile(pattern, re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style regex: {exc}") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Handle None or non-object inputs gracefully
        if request is None:
            return False

        # Helper to get attribute or dict key safely
        def get_value(obj, key):
            if isinstance(obj, dict):
                return obj.get(key)
            return getattr(obj, key, None)

        # 1. Check public message
        public_msg = get_value(request, 'public_message')
        if public_msg and isinstance(public_msg, str) and 'diaspora' in public_msg.lower():
            return True

        # 2. Check private message
        private_msg = get_value(request, 'private_message')
        if private_msg and isinstance(private_msg, str) and 'diaspora' in private_msg.lower():
            return True

        # 3. Check legacy payload
        payload = get_value(request, 'payload')
        if payload:
            if isinstance(payload, dict) and 'diaspora' in payload:
                return True
            if isinstance(payload, str) and 'diaspora' in payload.lower():
                return True

    except Exception:
        # Any unexpected error should result in a safe False
        return False

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            if "type" in request and "content" in request:
                req_type = request["type"]
                if isinstance(req_type, str) and (
                    req_type.startswith("m.") or req_type.startswith("org.matrix.")
                ):
                    return True
            return False

        # Handle object-like requests with attributes
        if hasattr(request, "type") and hasattr(request, "content"):
            req_type = getattr(request, "type")
            if isinstance(req_type, str) and (
                req_type.startswith("m.") or req_type.startswith("org.matrix.")
            ):
                return True

        return False
    except Exception:
        # Any unexpected error should result in a safe False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function accepts a datetime.datetime instance or an ISO‑formatted string.
    It returns the datetime in UTC as an ISO 8601 string ending with 'Z'.
    """
    # Validate input
    if dt is None:
        raise ValueError("dt cannot be None")

    # If a string is provided, try to parse it as ISO format
    if isinstance(dt, str):
        try:
            dt = datetime.datetime.fromisoformat(dt)
        except Exception as exc:
            raise ValueError(f"String dt must be in ISO format: {exc}") from exc

    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance or ISO string")

    # Ensure the datetime is timezone aware and in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)

    # Format as ISO 8601 with trailing 'Z'
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Add target and rel attributes to existing <a> tags
    def _add_attrs(match):
        tag = match.group(0)
        # Ensure the tag ends with '>'
        if not tag.endswith('>'):
            tag += '>'
        # Add target if missing
        if 'target=' not in tag.lower():
            tag = tag.rstrip('>') + ' target="_blank">'
        # Add rel if missing
        if 'rel=' not in tag.lower():
            tag = tag.rstrip('>') + ' rel="noopener noreferrer">'
        return tag

    a_tag_pattern = re.compile(r'<a\s+[^>]*href="[^"]+"[^>]*>', re.IGNORECASE)
    text = a_tag_pattern.sub(_add_attrs, text)

    # Linkify plain URLs
    url_pattern = re.compile(r'\b(https?://[^\s<]+)', re.IGNORECASE)

    def _linkify(match):
        url = match.group(1)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    # Avoid double-linking URLs that are already inside an <a> tag
    def _safe_linkify(match):
        start, end = match.span()
        # Check if the match is inside an <a> tag
        before = text.rfind('<a', 0, start)
        if before != -1:
            after = text.find('>', before)
            if after != -1 and after < start:
                # The URL is inside an existing <a> tag; leave it unchanged
                return match.group(0)
        return _linkify(match)

    text = url_pattern.sub(_safe_linkify, text)
    return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        # Ensure the input is a string
        if not isinstance(tag, str):
            return False

        # Strip leading/trailing whitespace
        tag = tag.strip()

        # Tag must not be empty
        if not tag:
            return False

        # Optional length constraint (e.g., max 30 characters)
        if len(tag) > 30:
            return False

        # Allowed characters: letters, digits, hyphen, underscore
        allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
        if not all(ch in allowed_chars for ch in tag):
            return False

        return True
    except Exception:
        # In case of any unexpected error, treat as invalid
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Return an empty dict for invalid or empty input
    if node is None:
        return {}
    try:
        # In ElementTree and lxml, iterating over the node yields its children
        children = list(node)
    except Exception:
        return {}
    result = {}
    for child in children:
        # Ensure the child has a tag attribute
        tag = getattr(child, 'tag', None)
        if tag is not None:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    url = url.strip()
    if not url:
        raise ValueError("url cannot be empty")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Determine the document path
    if document_path is None:
        document_path = "/nodeinfo/2.0"
    else:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        document_path = document_path.strip()
        if not document_path:
            document_path = "/nodeinfo/2.0"

    # Build the full href
    base = url.rstrip("/")
    path = document_path.lstrip("/")
    href = f"{base}/{path}"

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    doc = document.strip()
    # Try JSON format first
    try:
        json = __import__('json')
        data = json.loads(doc)
        if isinstance(data, dict):
            subject = data.get('subject')
            aliases = data.get('aliases', [])
            links = data.get('links', [])
            return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception:
        pass
    # Fallback to XRD (XML) format
    try:
        ET = __import__('xml.etree.ElementTree')
        root = ET.fromstring(doc)
        # Handle optional namespace
        ns = {}
        if root.tag.startswith('{'):
            uri, _, _ = root.tag[1:].partition('}')
            ns = {'ns': uri}
            subject_elem = root.find('ns:Subject', ns)
            alias_elems = root.findall('ns:Alias', ns)
            link_elems = root.findall('ns:Link', ns)
        else:
            subject_elem = root.find('Subject')
            alias_elems = root.findall('Alias')
            link_elems = root.findall('Link')
        subject = subject_elem.text if subject_elem is not None else None
        aliases = [e.text for e in alias_elems if e.text]
        links = []
        for le in link_elems:
            link = {k: v for k, v in le.attrib.items()}
            links.append(link)
        return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception:
        pass
    # If all parsing attempts fail, return an empty dict
    return {}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Basic validation of the handle
    if not isinstance(handle, str):
        return {}
    handle = handle.strip()
    if not handle:
        return {}
    if '@' not in handle:
        return {}
    try:
        local_part, domain = handle.rsplit('@', 1)
    except ValueError:
        return {}
    if not domain:
        return {}
    # Construct the webfinger URL
    try:
        import urllib.request
        import urllib.parse
        import json
        from urllib.error import URLError, HTTPError
    except Exception:
        # If imports fail, return empty dict
        return {}
    resource = f'acct:{handle}'
    query = urllib.parse.urlencode({'resource': resource})
    url = f'https://{domain}/.well-known/webfinger?{query}'
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return {}
            content_type = response.headers.get('Content-Type', '')
            data = response.read()
            try:
                # Decode bytes to string
                text = data.decode('utf-8')
                # Parse JSON
                result = json.loads(text)
                if isinstance(result, dict):
                    return result
                else:
                    return {}
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {}
    except (URLError, HTTPError, ValueError):
        return {}
    except Exception:
        return {}
    return {}

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file paths from the given directories that match the spec_option.

    Parameters
    ----------
    settings_dirs : list or tuple
        A list of directory paths to search for files.
    spec_option : str
        A file extension or suffix to filter files. If empty, all files are returned.

    Returns
    -------
    list
        Sorted list of full file paths that match the spec_option.

    Raises
    ------
    TypeError
        If `settings_dirs` is not a list/tuple or `spec_option` is not a string.
    """
    # Validate input types
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")

    import os

    matched_files = []

    for dir_path in settings_dirs:
        # Skip non-string entries
        if not isinstance(dir_path, str):
            continue

        # Skip if the directory does not exist
        if not os.path.isdir(dir_path):
            continue

        try:
            for root, _, files in os.walk(dir_path):
                for filename in files:
                    if spec_option:
                        if filename.endswith(spec_option):
                            matched_files.append(os.path.join(root, filename))
                    else:
                        matched_files.append(os.path.join(root, filename))
        except Exception:
            # If any error occurs while walking a directory, skip it
            continue

    return sorted(matched_files)

def ansible_config_manager(cls):
        """Gets the ansible config manager."""
        try:
            from ansible.constants import C
            return C
        except Exception as exc:
            raise RuntimeError(f"Unable to load Ansible config manager: {exc}") from exc

def workspace_manager(cls):
        """Gets the workspace manager. """
        try:
            # Lazily create a singleton workspace manager if it doesn't exist.
            if not hasattr(cls, "_workspace_manager") or cls._workspace_manager is None:
                # Attempt to import a concrete WorkspaceManager if available.
                try:
                    from .workspace_manager import WorkspaceManager  # type: ignore
                except Exception:
                    # Fallback to a simple placeholder object.
                    class _Placeholder:
                        """Fallback placeholder for the workspace manager."""
                        def __repr__(self):
                            return "<PlaceholderWorkspaceManager>"
                    WorkspaceManager = _Placeholder
                cls._workspace_manager = WorkspaceManager()
            return cls._workspace_manager
        except Exception as exc:
            # Wrap any unexpected error in a RuntimeError to provide context.
            raise RuntimeError("Unable to retrieve the workspace manager") from exc

def plugins_manager(cls):
    """Gets the plugin manager."""
    try:
        if cls is None:
            raise ValueError("cls cannot be None")
        if not hasattr(cls, "_plugins_manager"):
            # Lazy initialization of a simple plugin manager placeholder
            cls._plugins_manager = {}
        return cls._plugins_manager
    except Exception as exc:
        raise RuntimeError("Failed to get plugin manager") from exc

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No YAML file path provided")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                content = f.read()
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file '{yaml_file}': {exc}") from exc

        try:
            data = yaml.safe_load(content)
        except Exception as exc:
            raise IRValidatorException(f"Error parsing YAML file '{yaml_file}': {exc}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file '{yaml_file}' does not contain a mapping")

        # Determine required fields; subclasses may define REQUIRED_FIELDS
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in YAML file '{yaml_file}': {', '.join(missing)}")

        return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, 'spec', None)
        if spec is None:
            return defaults
        if isinstance(spec, dict):
            items = spec.items()
        elif isinstance(spec, (list, tuple)):
            items = spec
        else:
            raise TypeError("spec must be a dict or list/tuple")
        for key, value in items:
            if isinstance(value, dict) and 'default' in value:
                defaults[key] = value['default']
            else:
                defaults[key] = None
    except Exception as exc:
        raise RuntimeError(f"Error resolving spec defaults: {exc}") from exc
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    try:
        # If the instance already defines a mapping, use it
        if hasattr(self, 'deprecated_args'):
            return dict(self.deprecated_args)
        # Default mapping of deprecated options to their replacements
        return {
            'old_flag': 'new_flag',
            'legacy_mode': 'mode',
            'use_old_api': 'use_new_api',
        }
    except Exception:
        # In case of any unexpected error, return an empty mapping
        return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    try:
        # Retrieve the options dictionary; if it doesn't exist, treat as empty
        options_dict = getattr(self, "_command_options", {})
        if not isinstance(options_dict, dict):
            raise TypeError("Internal _command_options must be a dict")

        # Get the options for the requested command, defaulting to an empty list
        options = options_dict.get(command_name, [])
        if not isinstance(options, list):
            # If the stored value is not a list, attempt to convert it
            options = list(options)

        return options
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve parser options for '{command_name}': {exc}") from exc

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    if args is None:
        return silent
    try:
        # Handle dictionary of arguments
        if isinstance(args, dict):
            for key, value in args.items():
                if value is None or value is False:
                    silent.append(key)
            return silent

        # Handle list or tuple of arguments
        if isinstance(args, (list, tuple)):
            for item in args:
                # Tuple of (name, value)
                if isinstance(item, tuple) and len(item) == 2:
                    name, value = item
                    if value is None or value is False:
                        silent.append(name)
                    continue

                # String argument that might be considered silent
                if isinstance(item, str):
                    if item.startswith('_') or item.startswith('no_'):
                        silent.append(item)
                    continue

                # Object with 'silent' or 'is_silent' flag
                if hasattr(item, 'silent') and getattr(item, 'silent'):
                    name = getattr(item, 'name', None)
                    if name:
                        silent.append(name)
                    continue
                if hasattr(item, 'is_silent') and getattr(item, 'is_silent'):
                    name = getattr(item, 'name', None)
                    if name:
                        silent.append(name)
                    continue

                # Object with 'value' attribute that might be None or False
                if hasattr(item, 'value'):
                    if getattr(item, 'value') is None or getattr(item, 'value') is False:
                        name = getattr(item, 'name', None)
                        if name:
                            silent.append(name)
                    continue

                # Fallback: if item is a dict-like with a single key-value pair
                if isinstance(item, dict):
                    for key, value in item.items():
                        if value is None or value is False:
                            silent.append(key)
                    continue

            return silent
    except Exception:
        # In case of any unexpected error, return what we have collected so far
        return silent

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the list of required arguments from the instance
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("The instance does not define 'required_args'")

    if not isinstance(required, (list, tuple, set)):
        raise TypeError("'required_args' must be a list, tuple, or set")

    # Identify any missing arguments
    missing = [arg for arg in required if arg not in args or args[arg] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    # Ensure args is a dict for lookup
    if args is None:
        args = {}
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}
    # Iterate over options spec; support list of dicts or objects
    for opt in options_spec:
        # Get option name
        name = None
        if isinstance(opt, dict):
            name = opt.get("name")
            cond = opt.get("required_when")
        else:
            name = getattr(opt, "name", None)
            cond = getattr(opt, "required_when", None)
        if not name:
            continue
        if cond is None:
            continue
        # If condition is callable, call it with args
        if callable(cond):
            try:
                if cond(args):
                    required.append(name)
            except Exception:
                # ignore errors in condition evaluation
                pass
            continue
        # If condition is a boolean, use it directly
        if isinstance(cond, bool):
            if cond:
                required.append(name)
            continue
        # If condition is a string, evaluate it safely
        if isinstance(cond, str):
            try:
                # Use args as local variables for eval
                if eval(cond, {}, args):
                    required.append(name)
            except Exception:
                # ignore errors in eval
                pass
            continue
        # Unsupported condition type; ignore
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Validate input type
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    # Retrieve max length mapping from instance, if available
    max_lengths = getattr(self, 'max_lengths', {})
    if not isinstance(max_lengths, dict):
        max_lengths = {}
    # Iterate over provided arguments
    for name, value in args.items():
        # Determine the maximum allowed length for this argument
        max_len = max_lengths.get(name)
        if max_len is None:
            # No length restriction defined for this argument; skip validation
            continue
        # Ensure the maximum length is a non-negative integer
        if not isinstance(max_len, int) or max_len < 0:
            # Invalid configuration; skip validation
            continue
        # Skip validation for None values
        if value is None:
            continue
        # Attempt to obtain the length of the value
        try:
            current_len = len(value)
        except Exception:
            # Value does not support len(); skip validation
            continue
        # Compare lengths
        if current_len > max_len:
            raise ValueError(
                f"Argument '{name}' length {current_len} exceeds maximum allowed {max_len}"
            )
    return True

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    :raises TypeError: If args is not a mapping.
    :raises ValueError: If an argument value is not among its allowed choices.
    """
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the argument definitions; fall back to empty dict if not present
    arg_defs = getattr(self, "arguments", {})
    if not isinstance(arg_defs, dict):
        # If the attribute exists but is not a dict, ignore validation
        return

    for name, value in args.items():
        # Skip arguments that are not defined in the parser
        arg_def = arg_defs.get(name)
        if not arg_def:
            continue

        # Retrieve the list of allowed choices; skip if not defined
        choices = arg_def.get("choices")
        if not choices:
            continue

        # Ensure choices is iterable
        try:
            iter(choices)
        except TypeError:
            # If choices is not iterable, skip validation for this argument
            continue

        # Helper to validate a single value
        def _check(v):
            if v not in choices:
                raise ValueError(
                    f"Invalid value '{v}' for argument '{name}'. "
                    f"Expected one of {choices}."
                )

        # If the value is a collection (but not a string), validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                _check(v)
        else:
            _check(value)

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Validate input
    if args is None:
        return {}, {}
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of argument strings")

    control_args = {}
    nested_args = {}

    for arg in args:
        # Skip non-string entries
        if not isinstance(arg, str):
            continue

        # Strip leading dashes
        if arg.startswith("--"):
            key_val = arg[2:]
        elif arg.startswith("-"):
            key_val = arg[1:]
        else:
            key_val = arg

        # Split into key and value
        if "=" in key_val:
            key, val = key_val.split("=", 1)
        else:
            key, val = key_val, True

        # Skip empty keys
        if not key:
            continue

        # Normalize key (strip surrounding whitespace)
        key = key.strip()
        val = val.strip() if isinstance(val, str) else val

        # Determine category
        if key.lower().startswith("control_"):
            control_args[key] = val
        elif key.lower().startswith("custom_"):
            nested_args[key] = val
        elif key.lower().startswith("nested_"):
            nested_args[key] = val
        else:
            # Default to nested arguments
            nested_args[key] = val

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple")
        for item in extra_vars:
            if isinstance(item, dict):
                # Merge dictionary directly
                vars_dict.update(item)
            elif isinstance(item, str):
                # Expect format "key=value"
                if '=' in item:
                    key, value = item.split('=', 1)
                    key = key.strip()
                    if not key:
                        # Skip entries with empty key
                        continue
                    value = value.strip()
                    # Attempt to interpret value as JSON to support numbers, booleans, lists, etc.
                    try:
                        import json
                        parsed_value = json.loads(value)
                        vars_dict[key] = parsed_value
                    except Exception:
                        # Fallback to raw string if JSON parsing fails
                        vars_dict[key] = value
                else:
                    # Invalid format; skip silently
                    continue
            else:
                # Unsupported type; skip silently
                continue
        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level (int or str)
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: int exit code of the ansible-playbook command
    :raises FileNotFoundError: if playbook_path does not exist
    :raises RuntimeError: if ansible-playbook binary is not found or execution fails
    """
    # Validate playbook path
    if not playbook_path or not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a non-empty string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Build base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0 or verbose > 5:
                raise ValueError("verbose level must be between 0 and 5")
            cmd.extend(["-" + "v" * verbose])
        elif isinstance(verbose, str):
            # Accept strings like 'v', 'vv', 'vvv', etc.
            if not all(c == "v" for c in verbose):
                raise ValueError("verbose string must consist of 'v' characters")
            cmd.append("-" + verbose)
        else:
            raise TypeError("verbose must be int or str")

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars to JSON: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError(f"ansible_args key must be a string, got {type(key)}")
            # Convert key to --key format
            flag = f"--{key.lstrip('-')}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, skip adding the flag
            else:
                cmd.extend([flag, str(value)])

    # Add any environment variables from the plugin if available
    env = os.environ.copy()
    if hasattr(ir_plugin, "get_env") and callable(ir_plugin.get_env):
        try:
            plugin_env = ir_plugin.get_env()
            if isinstance(plugin_env, dict):
                env.update(plugin_env)
        except Exception:
            # Ignore plugin env errors to avoid breaking the playbook run
            pass

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook binary not found. Ensure Ansible is installed.") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Output handling
    if verbose:
        # Print stdout and stderr to the console
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

    # Raise if non-zero exit code
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=cmd,
            output=result.stdout,
            stderr=result.stderr
        )

    return result.returncode

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not plugin_dir:
        raise ValueError("plugin_dir must be provided")
    if not isinstance(plugin_dir, (str, bytes, os.PathLike)):
        raise TypeError("plugin_dir must be a string or path-like object")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory")

    # Look for a plugin spec file (plugin.json or plugin.yaml)
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if not spec_file:
        raise FileNotFoundError("No plugin spec file found in the directory")

    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                data = json.load(f)
            else:
                # For YAML, try to parse with json as a fallback if yaml is not available
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception:
                    # Fallback: treat as JSON
                    f.seek(0)
                    data = json.load(f)
    except (OSError, json.JSONDecodeError, ValueError) as e:
        raise ValueError(f"Failed to read or parse plugin spec: {e}") from e

    if not isinstance(data, dict):
        raise ValueError("Plugin spec root must be a JSON object/dictionary")

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
    except Exception as exc:
        raise RuntimeError("Failed to import os module") from exc

    # Environment variable name for the config path
    env_var = "CONFIG_PATH"

    # Only set the variable if it is not already defined
    if env_var not in os.environ:
        try:
            # Default to a config file named 'config.yaml' in the current working directory
            default_path = os.path.join(os.getcwd(), "config.yaml")
        except Exception as exc:
            raise RuntimeError("Failed to determine default config path") from exc

        try:
            os.environ[env_var] = default_path
        except Exception as exc:
            raise RuntimeError(f"Failed to set environment variable '{env_var}'") from exc
